mapper.update:
UPDATE mk_event_outbox
SET publish_state = 'SENDING',
    lease_owner = #{workerId},
    lease_until = #{leaseUntil},
    lease_version = #{newLeaseVersion}
WHERE tenant_id = #{tenantId}
  AND outbox_id = #{outboxId}
  AND lease_version = #{expectedLeaseVersion}
  AND published_at IS NULL
  AND dead_lettered_at IS NULL
  AND (
      (publish_state = 'PENDING' AND next_attempt_at <= #{now})
      OR (publish_state = 'SENDING' AND lease_until <= #{now})
  )

mapper.insert:
INSERT INTO mk_event_outbox_depth (
    scope_type, scope_id, bucket_id, pending_count, updated_at
) VALUES (
    #{scopeType}, #{scopeId}, #{bucketId}, 1, #{updatedAt}
)
ON DUPLICATE KEY UPDATE
    pending_count = pending_count + 1,
    updated_at = #{updatedAt}

mapper.update:
UPDATE mk_event_outbox_depth
SET pending_count = pending_count - 1,
    updated_at = #{updatedAt}
WHERE scope_type = #{scopeType}
  AND scope_id = #{scopeId}
  AND bucket_id = #{bucketId}
  AND pending_count > 0

mapper.select:
SELECT COALESCE(SUM(pending_count), 0)
FROM mk_event_outbox_depth
WHERE scope_type = #{scopeType}
  AND scope_id = #{scopeId}
